/**
 * Returns the icon for a technology by its Name (case-insensitive),
 * or undefined if there is no matching brand icon (caller should
 * fall back to the colored-dot design in that case).
 *
 * Some Technology rows in the DB have stray leading/trailing/doubled
 * whitespace in Name (e.g. " React", "  TypeScript") from manual entry,
 * and names like "Node.js" / "GitHub Actions" contain punctuation/spaces
 * that don't appear in the dot-free lookup keys below — so this strips
 * everything but letters/digits rather than only lowercasing.
 */
export function getTechIcon(name: string): TechIcon | undefined {
  const slug = name.trim().toLowerCase().replace(/[^a-z0-9]/g, "");
  return techIcons[slug];
}
